        "raw": "燃料等給油助成券配布事業\n\n新型コロナウィルス感染症の影響によりにより灯\n油、ガソリン等の燃料費が高騰し、町民の日常生\n配布した券の使用率が高かったことから効果的\n活に支障をきたしている。そのため、町民に対し\nだったと評価する。\n生活支援を行うため、各世帯に給油等助成券を発\n行し配布する。\n\n7,705\n\n",
