        "raw": "\n子ども、保護者（家庭）、教職員（学校）、地域の方です。\n\n⑵ 保育園年長児からの 〇（1）コロナ禍を乗り越え、これまでの取組等を見直しながら、 〇P９外国語指導助手（ALT）配置事業\n「まち未来科」（10\n\n教職員を含め家庭・地域の理解・啓発のための研修など、新た\n\n年プログラム）の実\n\nなスタートを期待します。\n\n践と検証\n⑶ 4 者対話による学校\nづくり会議の実施\n⑷ 「協同学習」の充実\n\n・委託先を選定するプロポーザル？\n⇒（事務局回答）\n\n〇（3）４者対話による学校づくり会議は、児童生徒が大人と意\n\n受託希望事業者からの提案内容を項目ごとに採点し、最優秀事\n\n見交換することはとても有意義なことであり、是非とも実施し",
