        "raw": "⑸学校給食調理業務 ター84％となり、昨年度よりそれぞれ 6％上昇した。\n委託事業\n\n園小中一斉の「おにぎり給食」を年 2 回実施した。各園・校が\n\n⑹食物アレルギーへ 工夫した取組を展開し、食育を推進している。\n\n重に取り組まれていると思うが、施設設備・人的対\n応による事を考慮し、過度に複雑な対応は控えるべ",
