        "raw": "\nエティ 5.0」の概念はかなり影響するのか。\n\nの充実を図りま 特別支援教育の充実に努めた。\n\nテクノロジーを活用した社会の仕組みづ\n\nす。\n⑴ 組織の充実・強化\n\n南部町教育の日及び教育月間啓発事業の推進では、10 月 8 日に「教育の\n\n集い」を開催した。\n『南部町教育振興基本計画 第Ⅱ期』第 5 章 めざす子 →（事務局回答）今の情報化社会の次の社会\n\n⑵ 主要な教育課題へ ども像、社会の姿としてまとめた 3 つの姿から、\n「心豊かに共に生きる町づ\nの取り組み\n\nくりはどのようなものを想定しているか。\nとしてソサイエティ 5.0 という新しい概念\n\nくり」を一つのポイントとして捉え意見交換ができる場を設定した。園・\n\nが示されている。学校教育においてもプロ",
