        "start": 2838,
        "raw": "■親元就農促進支援交付金事業\n①R4:1,200千円\n②R4:1,200千円\n③養豚における肥育・繁殖を主とする知識・技能を習得することで、養豚場経営\nの基礎を理解し、運営できるよう補助を行う。将来現在の経営主から親元就農者\n■農業研修生の受入、親元就農促進、集\nへの経営移譲を目指す\n落営農組織の育成、退職就農者の確保・\n④飼料価格の高騰や豚熱の感染拡大による被害が見込まれる\n33.3%\n支援などに努める\n■若桜町林業研究会育成事業費補助金、若桜町林業担い手奨学金支援助成金、鳥取",
        "note": "関連事業欄の明示された予算・決算・実施内容の単位。併記事業は分割せず、政策指標を事業評価に転用しない。金額列は未抽出。前年度比較値や公表年を対象年度と混同しない。"
