        "raw": "■女性活躍推進\n■現状は充て職等による登用が多く、目\n①歳出予算なし\n-100.0% 標を達成するためには、裾野を広げた啓\n②歳出予算なし\n発が必要であり時間を要する\n③町の審議会等における女性委員の割合（平均）の向上促進\n④各部局への継続的な周知・啓発が必要\n■年間数件の問い合わせはあるが、国の\n指導により設計監理を伴う修理修景が必 ■伝統的建造物群保存地区保存整備事業",
