        "raw": "■伝統的建造物群保存地区保存整備事業\n要となるため、補助率は高いものの通常\n①R4:13,097千円、R5:14,362千円\n12.0% より事業費が割高となり、住民の持ち出\n②R4:12,419千円、R5:0千円\nしが多くなる点や事業の指導監督を町で\n③伝建地区内の建物修理修景希望者への補助\nする必要があるため、修理件数を増やす\n④文化庁の基準に合わせた修理体制の確立、建物所有者への事業の周知\nのは難しい状況\n■昨年度より大きく上がった理由とし",
