        "raw": "\nR3～7年度の輝く中山間 ② 概ね順調であり、前年度と比較して徐々に地域団体の\nなった中 実績値 地域振\n60 地域創出事業（ソフト事 件 - 7 4 4 7 6 7 概ね 取組が増えている。今後より効果的な事業展開を図ると\n山間地域 (単年) 興課\n業）の取組件数の累計。 順調 ともに、地域づくり活動の定着と継続発展を図る。\n活性化の 実績値\n取組件数 (累計) 件 - - - 4 11 17 24\n(2403)\n魅力ある 達成率 ％ - - - 66.7% 84.6% 81.0% 80.0%\n中山間地\n域の振興\n目標値 人 - - - 280 285 290 295 300\n地域課題 令和６年度とっとりふるさとリーダーアカデミーで、\nの解決に 「とっとりふるさとリー 15名のリーダー認定者が生まれ、ゼミ生同士の交流を図\n61\n取り組む ダーアカデミー」で養成さ 実績値 ① ることができた。今後は、新テーマとして個人や団体組 地域振\n人 - 275 292 316 343 369 384\nリーダー れたリーダーの当該年度末 順調 織・グループの活動を横断的に結びつける横串連携ゼミ 興課\nの認定者 の人数。 を設置し、実践と連携の取組を増やしていく予定として\n数 いる。\n達成率 ％ - - - 112.9% 120.4% 127.2% 130.2%",
