        "raw": "を高め、利用者数及び売上金額を増加させてい\n麒麟のまち圏域での広域的な連携\n・利用者数 34,041人 麒麟のまち圏域の様々な魅力を、厳選食材を使 く必要がある。\n関西情報発信拠点推進事業 により、交流人口の増加、移住定 経済・雇用\n1 ○ ・売上金額 46,948,861円 用した料理や特産品の販売を行うことで、販路 令和７年度から新しい管理運営事業者に変わ 経済観光部 164\n費 住の促進、地元産品の販路拡大を 戦略課\n拡大や圏域のPRに貢献している。 り、事業者の強みを生かした麒麟のまち圏域の\n図る。\nPRを行う。リニューアルオープンによる集客数",
