        "start": 534,
        "raw": "及活動を推進する。太陽光発電パ ・誰にでも使いやすいアプリによって持続可能 スマホ・タブレットアプリのUI等を高齢者にも 今後も太陽光発電パネルガラスのリサイクルを\nネルガラスリサイクル材を活用し なまちづくりを目指す企業に経費の一部を支援 使いやすく改修し、住民サービスの向上や、持 行う企業や再生可能エネルギー100％の電力を\nた事業を推進する。 １件 続可能なまちづくりに貢献した。他にも、太陽 活用した農業を行う企業に支援を行い、「エネ スマートエ\nＳＤＧｓ未来都市推進事業\n2 ○ 【経済】環境面の取組を活用した ・地域資源（伝統文化）を活用し地域活性化を 光発電パネルガラスのリサイクルを行う企業 ルギーの地産地消」「企業による農業参入の推 経済観光部 ネルギータ 165\n費\n次世代農業の育成を推進する。 図る団体にプロジェクト経費の一部を支援 １ や、本市の取組について広報を行う企業にも各 進」「地域課題解決型ワーケーションの推進」 ウン推進室\n【社会】企業に対して、地域への 件 種支援を行い、SDGs未来都市計画の推進に貢献 を中心にして、SDGs未来都市計画の目標達成に\n継続的な関わりの機会を創出し、 ・鳥取市SDGs未来都市のステークホルダーが行 した。 向けて取り組んでいく。",
