        "raw": "事業\n本市に所在する大学または専門学 ・学生の麒麟のまち圏域への就職を促進する事 就職を理由とする若者の都市部への流出が続い\n校に通う学生を対象に、麒麟のま 業への補助 市内大学及び専門学校が学生に対して実施する ているため、市内の大学や専門学校が、学生を\n鳥取市・麒麟のまち圏域魅\n1 ○ ち圏域の企業への就職促進や地域 ・学生が麒麟のまち圏域に住み続けたいと思え 活動を支援することで、学生の地域への愛着心 対象に実施する麒麟のまち圏域の企業等への就 企画推進部 政策企画課 71\n力発見支援事業費\nの魅力の理解促進を図ることで、 るような魅力を発見するための事業への補助 の醸成や定住意欲の向上を図った。 職促進活動や魅力発見活動の支援を継続し、若\n若者定住につなげる。 補助件数４件（大学２件、専門学校２件） 者定住につなげていく。\n市民による文化芸術に関する事業への支援を実",
