        "raw": "・シティプロモーション「＃鳥取家族」とし 口減少など地域間競争は激化しており、本市な\n向上により、観光入込客数や移住 度より順位を上げたほか、制作動画は多くの再\nて、写真家・浅田政志氏をカメラマンに起用し らではの魅力を効果的に発信することの重要性\n鳥取市知名度アップ大作戦 定住者の増加を図るとともに、市 生回数と高評価を得ており、本市の知名度・認 秘書課\n3 ○ た著名人と市民の参加によるPRポスター製作 は高まっている。 企画推進部 72\n事業費 民愛着度の向上につなげていくこ 知度の向上につながった。（全国1,000市町村 広報室\n・「＃鳥取家族」と著名人のコラボによる動画 今後も引き続き、鳥取市で暮らすことの良さ、\nとで、住む人・来る人に愛され続 調査のうち、「認知度」令和５年度：28位→令\n制作・YouTube公開 魅力を全国に向けてPRし、関係人口や定住人口",
