        "start": 3530,
        "raw": "地震や水害などの災害時におい 要支援者の心身の状況、居住実態などを把握し\n避難行動要支援者の災害時の円滑な避難の実効\nて、障がいのある人、介護が必要 ているケアマネジャー等の福祉専門職の法人へ 災害時において要支援者が地域の「共助」によ\n避難行動要支援者支援制度 性を確保するため、地域の支援組織や福祉専門\n10 な高齢者などの要支援者が地域の 制度周知と作成依頼をした結果、24社の法人と り支援を受けられる体制づくりを、地域の支援 福祉部 地域福祉課 105\n普及促進事業費 職などと協働し、個別避難計画の作成に取り組\n「共助」により支援を受けられる 契約を交わし、更新を含む55件の個別避難計画 組織などと協働し、推進することができた。\nむ。\n体制づくりの推進を図る。 作成があった。",
