        "raw": "鳥取県、関係市町、JR西日本等で\nで公共交通事業の縮小が進んでいる。鉄道の減\n構成する「鳥取県東部鉄道利用促 鳥取県東部鉄道利用促進実行委員会において、\n鳥取県東部鉄道利用促進実 ・通勤モニターアンケート調査の実施 便や廃止は、住民生活や地域経済に大きな影響 都市整備\n3 ○ 進実行委員会」で、利用促進等の 利用促進に取り組んだほか、モニタリング調査 交通政策課 222\n行委員会負担金 ・各種利用促進に向けた取組の実施 を及ぼすことから、引き続き沿線自治体や関係 部\n取組を展開し、鉄道の確保維持を を実施して利用促進に向けた検討を行った。\n機関等と連携し、鉄道の維持・充実に向けた利\n図る。",
