        "raw": "・旅行商品造成支援の実施 3,449席\n官民連携組織「鳥取空港の利用を 鳥取空港の利用促進等の取組の展開により令和 鳥取-東京便の５便が令和11年３月まで維持さ\n・運賃助成の実施 264件\n鳥取空港の利用を促進する 促進する懇話会」で、鳥取東京便 11年３月までの鳥取－東京便の５便/日の継続 れることが決定したものの、５便の定期便化を 都市整備\n4 ○ ・首都圏でのプロモーション活動の実施 ２回 交通政策課 223\n懇話会負担金 の利用促進等の取組を展開し、地 が決定することとなり、地域産業・経済の振興 目指し、引き続き関係機関と連携し更なる利用 部\n・地元向けグループ旅行利用促進キャンペーン\n域産業・経済の振興を図る。 に寄与した。 促進に取り組む。\nの実施 計793席",
