        "raw": "湖東中学校校舎の長寿命化改良（２工区） のほか、昨今の気候変動や激甚化・頻発化する\n構造体の劣化対策やライフライン ［対象施設］教室棟（H４年建築）、管理・特別 災害への対策として文部科学省が推奨する空調\nの更新等により建物の耐久性を高 教室棟（S54建築、H４増築） 経年劣化による機能回復及び社会的要求に対応 整備やトイレ改修（洋式化等）、さらに今後、\n中学校大規模改造事業費 教育委員会\n17 ○ めるなど施設の長寿命化を図るこ ［改良内容］屋上防水、外壁断熱塗装、教室間 するための全面改修工事（長寿命化改良）を実 新設統合小学校の建設など大規模な施設整備が 教育総務課 342\n（令和５年度国１次補正） 事務局\nとにより、安全安心な教育環境の 仕切・建具・家具・廊下・階段・トイレの全面 施することで、快適な学習環境を確保した。 計画されており、財政を圧迫することが懸念さ\n確保を図る。 改修、空調整備など れる。引き続き、国への財政支援要望活動など\n［供用開始］令和７年３月26日 を展開し、長寿命化改良工事に係る有利財源の",
        "note": "令和6年度成果の個別事務事業表。事業名セルの折返しを、行番号と各行先頭の原文位置を個別確認して結合。同年度同名の他施策への再掲は重複除外。横長表の金額・成果・課題列は推測で分離せず、概要欄の令和7年度を実績年度にしない。",
