        "start": 2554,
        "raw": "や、移動販売と見守りを組み合わ 移動販売の運営や買い物福祉サービス（見守\nと見守りを組み合わせた買い物福祉サービス補 中山間地域の買い物環境の維持は、中山間地域\nせた買い物福祉サービスの取組を り）への支援\n中山間地域・買い物支援事 助を３件実施した。これにより、本市の中山間 で暮らす住民の安定的な暮らしに直結する。安\n5 ○ 支援することにより、買い物が困 【補助件数】 市民生活部 地域振興課 84\n業費 地域における買い物環境が確保され、食料品等 心安全な暮らしを確保するために、継続的な支\n難な地域における買い物環境の改 ・移動販売運営補助 ４件\nの日常の買い物が困難な状況に置かれている、 援を実施する。\n善を図るとともに、中山間地域住 ・買い物福祉サービス補助 ３件",
