        "note": "令和6年度成果の個別事務事業表。事業名セルの折返しを、行番号と各行先頭の原文位置を個別確認して結合。同年度同名の他施策への再掲は重複除外。横長表の金額・成果・課題列は推測で分離せず、概要欄の令和7年度を実績年度にしない。",
