        "raw": "支援会議を開催し、関係機関と連携を図りな\n活困窮者を対象に、生活に関わる 多様化・複雑化した内容となっている。さら\nがら実施。 相談者の属性や世代、相談内容に関わらず、包 鳥取市中央\n生活困窮者自立相談支援事 さまざまな相談に対応している。 に、世帯全体への包括的支援が必要な場合や、 総務部人\n1 括的に相談を受け止める体制や支援環境の整備 人権福祉セ 54\n業費 相談支援員が困りごとや不安を聞 困難が深刻化してから支援につながる場合もあ 権政策局\n令和４年度 16,051千円 を図る。 ンター\nいて課題を整理し、関係機関と連 り、「第２のセーフティネット」としての役割\n令和５年度 16,758千円",
